type UnionFind struct {
	parent, size []int
	parts        int // 集合的个数
}

func Constructor(n int) UnionFind {
	parent, size := make([]int, n), make([]int, n)
	for i := range parent {
		parent[i] = i // 一开始每个点自己是根
		size[i] = 1
	}
	return UnionFind{parent, size, n}
}

func (u *UnionFind) Find(x int) int {
	for u.parent[x] != x { // 往上走到根
		u.parent[x] = u.parent[u.parent[x]] // 路径压缩：指向爷爷
		x = u.parent[x]
	}
	return x
}

func (u *UnionFind) Unite(a, b int) bool {
	ra, rb := u.Find(a), u.Find(b)
	if ra == rb { // 已经在一个集合里
		return false
	}
	if u.size[ra] < u.size[rb] { // 小树挂到大树下面
		ra, rb = rb, ra
	}
	u.parent[rb] = ra
	u.size[ra] += u.size[rb]
	u.parts--
	return true
}

func (u *UnionFind) Connected(a, b int) bool {
	return u.Find(a) == u.Find(b)
}

func (u *UnionFind) Count() int {
	return u.parts
}

