        parent.resize(edges.size() + 1);            // 点的编号是 1 到 n
        iota(parent.begin(), parent.end(), 0);
        for (auto& e : edges) {
            int ru = find(e[0]), rv = find(e[1]);
            if (ru == rv) {                         // 已经连通，再连就成环了
