func findRedundantConnection(edges [][]int) []int {
	parent := make([]int, len(edges)+1) // 点的编号是 1 到 n
	for i := range parent {
		parent[i] = i
	}
	find := func(x int) int {
		for parent[x] != x {
			parent[x] = parent[parent[x]]
			x = parent[x]
		}
		return x
